	@Parameters(name = "{index}: test {0}, adminview {1}, groupsview {2}, create {3}, update {4}, delete {5}, useradd {6}, userupdate {7}, perm {8}")
	public static Collection<Object[]> data() {
		Collection<Object[]> data = new ArrayList<>();

