			return object.getParts();
		} catch (NullPointerException e) {
			logger.error("Error while getting parts, tag type {" + id + "} was not found", e);
		} catch (NodeException e) {
			logger.error("Error while getting parts for tag type {" + id + "}", e);
		}

		return null;
	}

	/**
