		coll = NodeTestUtils.getObjects(ds, dsRule, 0, 400);
		logger.debug("--------------");
		logger.debug("Object HitCount  : " + (objectCache.getHitCountRam() - objectHitCount) + "  (before: " + objectHitCount + ")");
