		byte[] binaryData = (byte[]) data;

		assertEquals("Check size of binary data", BINARYDATA.length, binaryData.length);
		for (int j = 0; j < binaryData.length; j++) {
			assertEquals("Check data[" + j + "]", BINARYDATA[j], binaryData[j]);
