								// if the requested permbit is not set, filter the object
								if (!permHandler.checkPermissionBit(Folder.TYPE_FOLDER, privFolderId, priv.getPermBit())) {
									return false;
								}
							}
						}

						// all requested privileges found for the group, it is not filtered
