			}

			// now apply the filters
			filter.filter(groups);

			// optionally reduce the list of groups (if requested)
			if (reduce != null) {
				switch (reduce) {
				case child:
					groups = UserGroup.reduceUserGroups(groups, ReductionType.CHILD);
					break;

