			PreparedStatement pst = null;
			ResultSet res = null;

			try {
				pst = t.prepareStatement("SELECT id FROM objtag WHERE obj_type = ? AND obj_id = ? AND name = ?");
				pst.setInt(1, t.getTType(containerClass));
				pst.setInt(2, 0);
