				.perms(permFunction(perms, ObjectPermission.view, ObjectPermission.edit, ObjectPermission.delete))
				.sort(ResolvableComparator.get(sorting, "id", "name", "description", "command", "cdate", "edate"))
				.page(paging)
				.to(new TaskListResponse());

			trx.success();
			return response;
		}
