			 */
			if (channelIdToUpdate == i) {
				attributeToChange = object;
			}
		}

		// now run a sync into the target datasource
		MCCRSync sync = new MCCRSync(ds, targetDS, false, true, true, true, true, 100, null);

		sync.doSync();

		// Iterate through channel IDs
		for (int i = 1; i <= 3; i++) {

