	@Override
	public boolean isVersioningSupported(Class<? extends NodeObject> clazz) {
		// ds and ds_obj support versioning
		if (DatasourceEntry.class.equals(clazz)) {
			return true;
		} else if (Datasource.class.equals(clazz)) {
			return true;
		} else {
			return false;
