	}),

	/**
	 * Task that purges inbox messages
	 */
	purgemessages("Purge Inbox Messsages", "Purge inbox messages, which are older than the configured maximum message age", out -> {
		PurgeMessagesJob job = new PurgeMessagesJob();
		job.purge(out);
