		@Override
		public void clearQueue() throws NodeException {
			Transaction t = TransactionManager.getCurrentTransaction();
			pubQueueUserId = 0;
			offQueueUserId = 0;
			timePubQueue = new ContentNodeDate(0);
			timePubVersionQueue = null;
			timeOffQueue = new ContentNodeDate(0);
