public class TablePartType extends AbstractPartType {

	private static final String LINE_SEPARATOR = "\n";

	private static final String TABLE_PREFIX = "table.";

	private static final String TABLEHEADER_PREFIX = "table+.";

	private static final String STYLE_POSTFIX = ".style";

	private int rows = -1;

	private int cols = -1;

	/**
	 * Threadlocal for the current row counter
	 */
	private ThreadLocal<Integer> rowLocal = new ThreadLocal<Integer>();

	/**
	 * Threadlocal for the current col counter
	 */
	private ThreadLocal<Integer> colLocal = new ThreadLocal<Integer>();

	private Tag tag;

	private static final String TR_PREFIX = "tr.";

	private String tagName;

	private static final String TD_PREFIX = "td.";

	private static final Icon ICO_TAB_FORMAT = new Icon("content", "tab_format.gif", "");

	/**
	 * Create an instance of the parttype
	 * @param value value of the parttype
	 * @throws NodeException
	 */
	public TablePartType(Value value) throws NodeException {
		super(value);
	}

	/*
	 * (non-Javadoc)
	 * @see com.gentics.contentnode.object.parttype.PartType#setValue(com.gentics.contentnode.object.Value)
	 */
	public void setValue(Value value) throws NodeException {
		super.setValue(value);
	}

	/*
	 * (non-Javadoc)
	 * @see com.gentics.contentnode.object.parttype.PartType#isEmpty()
	 */
	public boolean isMandatoryAndNotFilledIn() throws NodeException {
		if (!isRequired()) {
			return false;
		}

		reloadSettings();

		if (rows <= 0 || cols <= 0) {
			return true;
		} else {
			return false;
		}
	}

	/**
	 * Reload the table
	 * @throws NodeException
	 */
	private void reloadValue() throws NodeException {
		reloadSettings();

		tag = null;
		tagName = "";

		ValueContainer valueContainer = getValueObject().getContainer();

		if (valueContainer instanceof Tag) {
			tag = (Tag) valueContainer;
			tagName = tag.getName();
		}
	}

	/**
	 * Reload the settings for the table
	 */
	private void reloadSettings() {
		String[] parts = ObjectTransformer.getString(getValueObject().getValueText(), "").split(";");
		String sCols = parts.length > 0 ? parts[0] : "0";
		String sRows = parts.length > 1 ? parts[1] : "0";

		try {
			rows = Integer.parseInt(sRows);
			cols = Integer.parseInt(sCols);
		} catch (NumberFormatException e) {
			rows = 0;
			cols = 0;
			NodeLogger.getLogger(this.getClass()).warn(e);
		}
	}

	/*
	 * (non-Javadoc)
	 * @see com.gentics.contentnode.object.parttype.PartType#hasTemplate()
	 */
	public boolean hasTemplate() throws NodeException {
		return false;
	}

	/*
	 * (non-Javadoc)
	 * @see com.gentics.lib.render.TemplateRenderer#render(com.gentics.lib.render.RenderResult,
	 *      java.lang.String)
	 */
	public String render(RenderResult result, String template) throws NodeException {
		super.render(result, template);
		if (tag == null) {
			reloadValue();
		}

		RenderType renderType = TransactionManager.getCurrentTransaction().getRenderType();
		// TODO get the edit color from the config?
		String editCol = "#DDDDDD";
		StringWriter JS = new StringWriter();

		if (tag == null) {
			// TODO error handling
			// cannot render a table without other tags
			return "";
		}

		// special hack to prevent rendering of table tag within .style-tags
		if (tagName.endsWith(STYLE_POSTFIX)) {
			return "";
		}

		StringBuffer code = new StringBuffer();

		List parts = getValueObject().getPart().getConstruct().getParts();

		TagContainer tagContainer = tag.getContainer();
		String containerType = "content";

		if (tagContainer instanceof Content) {
			// replace the content by the currently rendered page
			tagContainer = renderType.getTopmostTagContainer();
		} else if (tagContainer instanceof Template) {
			containerType = "template";
		}

		// edit mode
		int editMode = renderType.getEditMode();

		if (editMode == RenderType.EM_EDIT) {
			// create a lot of JS output
			VelocityContext context = new VelocityContext();

			context.put("name", tag.getName());
			context.put("cols", new Integer(cols));
			context.put("rows", new Integer(rows));
			context.put("editcol", editCol);
			// TODO what the heck is info0, info1, info2?
			String infoText = getValueObject().getPart().getInfoText();

			if (infoText == null) {
				infoText = "";
			}
			String[] infoParts = infoText.split(";");

			context.put("info0", Boolean.valueOf(infoParts.length > 0 && !StringUtils.isEmpty(infoParts[0]) && !"0".equals(infoParts[0])));
			context.put("info1", Boolean.valueOf(infoParts.length > 1 && !StringUtils.isEmpty(infoParts[1]) && !"0".equals(infoParts[1])));
			context.put("info2", Boolean.valueOf(infoParts.length > 2 && !StringUtils.isEmpty(infoParts[2]) && !"0".equals(infoParts[2])));
			// put an i18n helper
			context.put("i18n", new I18nWrapper());
			// choose correct DO (depending on whether this is edit or realedit mode)
			context.put("DO", editMode == RenderType.EM_EDIT ? "14002" : "14012");
			context.put("mother_type", containerType);
			context.put("tag_id", tag.getId());
			context.put("STAG", renderType.getRenderUrl(null, null));
			try {
				Velocity.evaluate(context, JS, "tableparttype_" + Thread.currentThread().getName(),
						new InputStreamReader(getClass().getResourceAsStream("javascript.vm"), "UTF-8"));

				// If there is already a parameter 'gentics.JS' we append it to the new value.
				String[] oldJs = (String[]) result.getParameters().get("gentics.JS");

				if (oldJs != null && oldJs.length > 0) {
					JS.write(oldJs[0]);
				}

				// TODO maybe we can use addParameter here, and output all 
				// elements of the array in PHP ?
				result.setParameter("gentics.JS", JS.toString());
			} catch (Exception e) {
				throw new NodeException("Error while rendering table in edit mode", e);
			}

			code.append("\n<form name=\"form_").append(tag.getName()).append("\">");
		}

		code.append("<table");
		String additionalTags = "";

		for (int i = 0; i < parts.size(); i++) {
			Part part = (Part) parts.get(i);
			String keyname = part.getKeyname();

			if (keyname == null) {
				continue;
			}

			if (keyname.startsWith(TABLE_PREFIX)) {

				appendProperty(renderType, result, code, tag, keyname, TABLE_PREFIX);

			} else if (keyname.startsWith(TABLEHEADER_PREFIX)) {
				additionalTags += addInnerTableTag(part, result);
			}
		}

		code.append(">");
		code.append(LINE_SEPARATOR);
		code.append(additionalTags);
		code.append(LINE_SEPARATOR);

		// edit mode
		if (editMode == RenderType.EM_EDIT) {
			code.append("<tr bgcolor=\"").append(editCol).append("\" id=\"").append(tag.getName()).append("_markhead\">\n");
			// TODO editlink
			String editLink = renderType.getRenderUrl(null, null).toString() + "&do=10008&id=" + tag.getId() + "&type=" + containerType + "&keepsid=1&t_table=1";

			code.append("<td nowrap align=\"center\" valign=\"middle\" width=\"1%\"><a href=\"javascript:hopedit('").append(editLink).append("')\">").append(ICO_TAB_FORMAT.getHTML(0, null, null, null, null, null, null, null)).append(
					"</a></td>");
			for (int col = 1; col <= cols; col++) {
				char c = (char) (64 + col);

				code.append("<td align=\"center\" nowrap>\n<input type=checkbox onclick=\"mark_").append(tag.getName()).append("();\">").append(c).append(
						"</td>\n");
			}
			code.append("</tr>\n");
		}

		int row;

		for (row = 1; row <= rows; row++) {
			rowLocal.set(row);

			code.append("<tr");

			Tag rowStyle = tagContainer.getTag(getTagName(row, 0, true));

			// this is a bit of a hack, we push the tag to the rendertype
			// and remove it from the stack immediately. this is only to
			// make sure that the caller noticed that we used it
			if (rowStyle != null) {
				renderType.push(rowStyle);
				renderType.pop();
			}

			appendProperties(renderType, result, code, rowStyle, parts, TR_PREFIX);

			code.append(">");
			code.append(LINE_SEPARATOR);

			// edit mode
			if (editMode == RenderType.EM_EDIT) {
				code.append("<td id=\"").append(tag.getName()).append("_mark").append(row).append("\" valign=\"middle\" align=\"right\" bgcolor=\"").append(editCol).append("\" nowrap>\n<input type=checkbox onClick=\"mark_").append(tag.getName()).append("();\">").append(row).append(
						"&nbsp;</td>\n");
			}

			// store lenght of code before tag content is added
			int lengthBefore;

			int col;

			for (col = 1; col <= cols; col++) {
				colLocal.set(col);

				Tag cellStyle = tagContainer.getTag(getTagName(row, col, true));

				// this is a bit of a hack, we push the tag to the rendertype
				// and remove it from the stack immediately. this is only to
				// make sure that the caller noticed that we used it
				if (cellStyle != null) {
					renderType.push(cellStyle);
					renderType.pop();
				}

				StringBuffer cellCode = new StringBuffer();

				// edit mode
				if (editMode == RenderType.EM_EDIT) {
					cellCode.append(" id=\"").append(tag.getName()).append("-").append(col).append("-").append(row).append("\"");
				}

				String cellhtml = "td";

				if (appendProperties(renderType, result, cellCode, cellStyle, parts, TD_PREFIX) && row == 1) {
					cellhtml = "th";
				}

				code.append('<').append(cellhtml).append(cellCode);
				code.append(">");
				code.append(LINE_SEPARATOR);

				Tag cellTag = tagContainer.getTag(getTagName(row, col, false));

				lengthBefore = code.length();
				if (cellTag != null) {
					// edit mode
					if ((editMode == RenderType.EM_EDIT) && cellTag.isEditable()) {
