	public void deleteLanguage(FactoryContentLanguage lang) throws NodeException {
		Transaction t = TransactionManager.getCurrentTransaction();
		Collection deleteList = getDeleteList(t, ContentLanguage.class);

		deleteList.add(lang);
	}

