		TIMESTAMP_ADDOBJECT = 2000 + TIMESTAMP_NOW;
		TIMESTAMP_LINKOBJECT = 3000 + TIMESTAMP_NOW;
		TIMESTAMP_REMOVELINK = 4000 + TIMESTAMP_NOW;
		TIMESTAMP_ADDATTRIBUTE = 5000 + TIMESTAMP_NOW;
