		protected Set<Integer> getMasterNodeIds() throws NodeException {
			Set<Integer> masterNodeIds = new HashSet<Integer>();
			masterNodeIds.add(0);
			Node channel = getChannel();
			if (channel != null) {
				for (Node master : channel.getMasterNodes()) {
