		info(String.format("Wait for schema migration status for '%s'", cr.getName()));
		Map<String, Map<String, Long>> unmigratedSchemas = new HashMap<>();

		while (!checkSchemaStatus(unmigratedSchemas)) {
			try {
				Thread.sleep(POLL_INTERVAL_MS);
