			page = new ObjectTypeBean();
			page.setType(new Integer(Page.TYPE_PAGE));
			page.setName("page");
			page.setExcludeVersioning(false);

			file = new ObjectTypeBean();
			file.setType(new Integer(ContentFile.TYPE_FILE));
			file.setName("file");
			file.setExcludeVersioning(false);
		}

		/*
		 * (non-Javadoc)
