							new ObjectAttributeBean("content_languages", GenticsContentAttribute.ATTR_TYPE_TEXT, false, null, true, Page.TYPE_PAGE, 0, null, null,
							null, false, false));
				}

				if (!pageAttributeNames.contains("content_language")) {
